using CleanArchitecture.Blazor.Application.Features.Subsystems.DTOs;
using CleanArchitecture.Blazor.Application.Features.Subsystems.Caching;
using CleanArchitecture.Blazor.Application.Features.Systems.DTOs;

namespace CleanArchitecture.Blazor.Application.Features.Subsystems.Queries.GetHierarchy;

public class GetSystemHierarchyQuery : ICacheableRequest<Result<SystemHierarchyDto>>
{
   public required int SystemId { get; set; }
   public string CacheKey => SubsystemCacheKey.GetHierarchyCacheKey($"{SystemId}");
   public IEnumerable<string>? Tags => SubsystemCacheKey.Tags;
}

public class GetSystemHierarchyQueryHandler : IRequestHandler<GetSystemHierarchyQuery, Result<SystemHierarchyDto>>
{
    private readonly IApplicationDbContextFactory _dbContextFactory;
    private readonly IMapper _mapper;

    public GetSystemHierarchyQueryHandler(
        IApplicationDbContextFactory dbContextFactory,
        IMapper mapper
    )
    {
        _dbContextFactory = dbContextFactory;
        _mapper = mapper;
    }

    public async Task<Result<SystemHierarchyDto>> Handle(GetSystemHierarchyQuery request, CancellationToken cancellationToken)
    {
        await using var db = await _dbContextFactory.CreateAsync(cancellationToken);
        
        var system = await db.Systems
                            .Include(s => s.Subsystems)
                            .Where(s => s.Id == request.SystemId)
                            .ProjectTo<SystemHierarchyDto>(_mapper.ConfigurationProvider)
                            .FirstOrDefaultAsync(cancellationToken);

        if (system == null)
        {
            return await Result<SystemHierarchyDto>.FailureAsync($"System with id: [{request.SystemId}] not found.");
        }

        return await Result<SystemHierarchyDto>.SuccessAsync(system);
    }
}